import{_ as e,o as n,c as r,a0 as i}from"./chunks/framework.DCluYYrN.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"id_ID/guide/faq.md","filePath":"id_ID/guide/faq.md"}'),k={name:"id_ID/guide/faq.md"};function u(t,a,d,l,m,s){return n(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="apakah-kernelsu-mendukung-perangkat-saya" tabindex="-1">Apakah KernelSU mendukung perangkat saya? <a class="header-anchor" href="#apakah-kernelsu-mendukung-perangkat-saya" aria-label="Permalink to &quot;Apakah KernelSU mendukung perangkat saya?&quot;">​</a></h2><p>KernelSU mendukung perangkat yang menjalankan Android dengan bootloader yang tidak terkunci. Namun, dukungan resmi hanya untuk GKI Linux Kernel 5.10+ (dalam praktiknya, ini berarti perangkat Anda harus memiliki Android 12 out-of-the-box agar didukung).</p><p>Anda dapat dengan mudah memeriksa dukungan untuk perangkat Anda melalui aplikasi manajer KernelSU, yang tersedia <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">di sini</a>.</p><p>Jika aplikasi menunjukkan <code>Not installed</code>, berarti perangkat Anda secara resmi didukung oleh KernelSU.</p><p>Jika aplikasi menunjukkan <code>Unsupported</code>, berarti perangkat Anda tidak didukung secara resmi saat ini. Namun, Anda dapat membangun kode sumber kernel dan mengintegrasikan KernelSU untuk membuatnya bekerja, atau gunakan <a href="./unofficially-support-devices.html">Perangkat yang didukung tidak resmi</a>.</p><h2 id="apakah-kernelsu-membutuhkan-buka-bootloader" tabindex="-1">Apakah KernelSU membutuhkan buka bootloader? <a class="header-anchor" href="#apakah-kernelsu-membutuhkan-buka-bootloader" aria-label="Permalink to &quot;Apakah KernelSU membutuhkan buka bootloader?&quot;">​</a></h2><p>Ya, tentu saja.</p><h2 id="apakah-kernelsu-mendukung-modul" tabindex="-1">Apakah KernelSU mendukung modul? <a class="header-anchor" href="#apakah-kernelsu-mendukung-modul" aria-label="Permalink to &quot;Apakah KernelSU mendukung modul?&quot;">​</a></h2><p>Ya, sebagian besar modul Magisk bekerja di KernelSU. Namun, jika modul Anda perlu memodifikasi file <code>/system</code>, Anda perlu menginstal <a href="./metamodule.html">metamodule</a> (seperti <code>meta-overlayfs</code>). Fitur modul lainnya bekerja tanpa metamodule. Periksa <a href="./module.html">Panduan modul</a> untuk info lebih lanjut.</p><h2 id="apakah-kernelsu-mendukung-xposed" tabindex="-1">Apakah KernelSU mendukung Xposed? <a class="header-anchor" href="#apakah-kernelsu-mendukung-xposed" aria-label="Permalink to &quot;Apakah KernelSU mendukung Xposed?&quot;">​</a></h2><p>Ya, Anda dapat menggunakan LSPosed (atau turunan Xposed modern lainnya) dengan <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a>.</p><h2 id="apakah-kernelsu-mendukung-zygisk" tabindex="-1">Apakah KernelSU mendukung Zygisk? <a class="header-anchor" href="#apakah-kernelsu-mendukung-zygisk" aria-label="Permalink to &quot;Apakah KernelSU mendukung Zygisk?&quot;">​</a></h2><p>KernelSU tidak memiliki dukungan Zygisk bawaan, tetapi Anda dapat menggunakan modul seperti <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> untuk mendukungnya.</p><h2 id="apakah-kernelsu-kompatibel-dengan-magisk" tabindex="-1">Apakah KernelSU kompatibel dengan Magisk? <a class="header-anchor" href="#apakah-kernelsu-kompatibel-dengan-magisk" aria-label="Permalink to &quot;Apakah KernelSU kompatibel dengan Magisk?&quot;">​</a></h2><p>Sistem modul KernelSU bertentangan dengan magic mount Magisk. Jika ada modul yang diaktifkan di KernelSU, maka seluruh Magisk akan berhenti bekerja.</p><p>Namun, jika Anda hanya menggunakan <code>su</code> dari KernelSU, ini akan bekerja dengan baik dengan Magisk. KernelSU memodifikasi <code>kernel</code>, sedangkan Magisk memodifikasi <code>ramdisk</code>, memungkinkan keduanya bekerja bersama.</p><h2 id="akankah-kernelsu-menggantikan-magisk" tabindex="-1">Akankah KernelSU menggantikan Magisk? <a class="header-anchor" href="#akankah-kernelsu-menggantikan-magisk" aria-label="Permalink to &quot;Akankah KernelSU menggantikan Magisk?&quot;">​</a></h2><p>Kami percaya tidak, dan itu bukan tujuan kami. Magisk sudah cukup baik untuk solusi root userspace dan akan memiliki umur yang panjang. Tujuan KernelSU adalah untuk menyediakan antarmuka kernel kepada pengguna, bukan untuk menggantikan Magisk.</p><h2 id="dapatkah-kernelsu-mendukung-perangkat-non-gki" tabindex="-1">Dapatkah KernelSU mendukung perangkat non-GKI? <a class="header-anchor" href="#dapatkah-kernelsu-mendukung-perangkat-non-gki" aria-label="Permalink to &quot;Dapatkah KernelSU mendukung perangkat non-GKI?&quot;">​</a></h2><p>Ada kemungkinan. Tetapi Anda harus mengunduh sumber kernel dan mengintegrasikan KernelSU ke dalam source tree, dan mengkompilasi kernel sendiri.</p><h2 id="dapatkah-kernelsu-mendukung-perangkat-di-bawah-android-12" tabindex="-1">Dapatkah KernelSU mendukung perangkat di bawah Android 12? <a class="header-anchor" href="#dapatkah-kernelsu-mendukung-perangkat-di-bawah-android-12" aria-label="Permalink to &quot;Dapatkah KernelSU mendukung perangkat di bawah Android 12?&quot;">​</a></h2><p>Kernel perangkat yang mempengaruhi kompatibilitas KernelSU, dan tidak ada hubungannya dengan versi Android. Satu-satunya batasan adalah bahwa perangkat yang diluncurkan dengan Android 12 harus memiliki versi kernel 5.10+ (perangkat GKI). Jadi:</p><ol><li>Perangkat yang diluncurkan dengan Android 12 harus didukung.</li><li>Perangkat dengan kernel lama (beberapa perangkat dengan Android 12 juga memiliki kernel lama) kompatibel (Anda harus membangun kernel sendiri).</li></ol><h2 id="dapatkah-kernelsu-mendukung-kernel-lama" tabindex="-1">Dapatkah KernelSU mendukung kernel lama? <a class="header-anchor" href="#dapatkah-kernelsu-mendukung-kernel-lama" aria-label="Permalink to &quot;Dapatkah KernelSU mendukung kernel lama?&quot;">​</a></h2><p>Ada kemungkinan. KernelSU sekarang telah di-backport ke kernel 4.14. Untuk kernel yang lebih lama, Anda perlu melakukan backport secara manual, dan PR selalu diterima!</p><h2 id="bagaimana-cara-mengintegrasikan-kernelsu-untuk-kernel-lama" tabindex="-1">Bagaimana cara mengintegrasikan KernelSU untuk kernel lama? <a class="header-anchor" href="#bagaimana-cara-mengintegrasikan-kernelsu-untuk-kernel-lama" aria-label="Permalink to &quot;Bagaimana cara mengintegrasikan KernelSU untuk kernel lama?&quot;">​</a></h2><p>Silakan periksa panduan <a href="./how-to-integrate-for-non-gki.html">Integrasi untuk perangkat non-GKI</a>.</p><h2 id="mengapa-versi-android-saya-13-dan-kernel-menunjukkan-android12-5-10" tabindex="-1">Mengapa versi Android saya 13, dan kernel menunjukkan &quot;android12-5.10&quot;? <a class="header-anchor" href="#mengapa-versi-android-saya-13-dan-kernel-menunjukkan-android12-5-10" aria-label="Permalink to &quot;Mengapa versi Android saya 13, dan kernel menunjukkan &quot;android12-5.10&quot;?&quot;">​</a></h2><p>Versi kernel tidak ada hubungannya dengan versi Android. Jika Anda perlu mem-flash kernel, selalu gunakan versi kernel; versi Android tidak sepenting itu.</p><h2 id="saya-gki-1-0-bisakah-saya-menggunakan-ini" tabindex="-1">Saya GKI 1.0, bisakah saya menggunakan ini? <a class="header-anchor" href="#saya-gki-1-0-bisakah-saya-menggunakan-ini" aria-label="Permalink to &quot;Saya GKI 1.0, bisakah saya menggunakan ini?&quot;">​</a></h2><p>GKI 1.0 sama sekali berbeda dari GKI 2.0, Anda harus mengkompilasi kernel sendiri.</p><h2 id="bagaimana-cara-membuat-system-rw" tabindex="-1">Bagaimana cara membuat <code>/system</code> RW? <a class="header-anchor" href="#bagaimana-cara-membuat-system-rw" aria-label="Permalink to &quot;Bagaimana cara membuat `/system` RW?&quot;">​</a></h2><p>Kami tidak merekomendasikan Anda memodifikasi partisi sistem secara langsung. Silakan periksa <a href="./module.html">Panduan modul</a> untuk memodifikasinya secara systemless. Jika Anda bersikeras melakukan ini, periksa <a href="https://github.com/HuskyDG/magic_overlayfs" target="_blank" rel="noreferrer">magisk_overlayfs</a>.</p><h2 id="bisakah-kernelsu-memodifikasi-hosts-bagaimana-cara-menggunakan-adaway" tabindex="-1">Bisakah KernelSU memodifikasi hosts? Bagaimana cara menggunakan AdAway? <a class="header-anchor" href="#bisakah-kernelsu-memodifikasi-hosts-bagaimana-cara-menggunakan-adaway" aria-label="Permalink to &quot;Bisakah KernelSU memodifikasi hosts? Bagaimana cara menggunakan AdAway?&quot;">​</a></h2><p>Tentu saja. Tetapi KernelSU tidak memiliki dukungan hosts bawaan, Anda dapat menginstal modul seperti <a href="https://github.com/symbuzzer/systemless-hosts-KernelSU-module" target="_blank" rel="noreferrer">systemless-hosts</a> untuk melakukannya.</p><h2 id="mengapa-modul-saya-tidak-bekerja-setelah-instalasi-baru" tabindex="-1">Mengapa modul saya tidak bekerja setelah instalasi baru? <a class="header-anchor" href="#mengapa-modul-saya-tidak-bekerja-setelah-instalasi-baru" aria-label="Permalink to &quot;Mengapa modul saya tidak bekerja setelah instalasi baru?&quot;">​</a></h2><p>Jika modul Anda perlu memodifikasi file <code>/system</code>, Anda perlu menginstal <a href="./metamodule.html">metamodule</a> untuk me-mount direktori <code>system</code>. Fitur modul lainnya (skrip, sepolicy, system.prop) bekerja tanpa metamodule.</p><p><strong>Solusi</strong>: Lihat <a href="./metamodule.html">Panduan Metamodule</a> untuk instruksi instalasi.</p><h2 id="apa-itu-metamodule-dan-mengapa-saya-membutuhkannya" tabindex="-1">Apa itu metamodule dan mengapa saya membutuhkannya? <a class="header-anchor" href="#apa-itu-metamodule-dan-mengapa-saya-membutuhkannya" aria-label="Permalink to &quot;Apa itu metamodule dan mengapa saya membutuhkannya?&quot;">​</a></h2><p>Metamodule adalah modul khusus yang menyediakan infrastruktur untuk me-mount modul reguler. Lihat <a href="./metamodule.html">Panduan Metamodule</a> untuk penjelasan lengkap.</p>',41)])])}const h=e(k,[["render",u]]);export{g as __pageData,h as default};
